import re,glob,collections
d=collections.defaultdict(collections.Counter)
for f in sorted(glob.glob('*.log')):
    t=open(f).read()
    for m in re.finditer(r'^---- (?:FAIL|ERROR): (\S+)\n(.*?)(?=^---- |^result|^run cancelled|\Z)',t,re.S|M if False else re.S|re.M):
        body=m.group(2).strip().splitlines()
        d[m.group(1)][ '\n'.join(body[-3:])[:400]]+=1
for k,v in d.items():
    print('###',k)
    for s,c in v.items(): print(c,s,'\n--')
